#!/usr/bin/env bash
# Flip GTK between light and dark (gtk-application-prefer-dark-theme).
# Colors are regenerated by the gtk-theme listener (or here, when it is not running).
source "$(dirname "$(readlink -f "$0")")/../lib.sh"

KEY="gtk-application-prefer-dark-theme"

if [ ! -f "$GTK3_SETTINGS_FILE" ]; then
    error "$GTK3_SETTINGS_FILE not found."
    exit 1
fi

if [ "$(current_mode)" = dark ]; then
    gtk3_value=0; gtk4_value=false; message="Switched to light theme."
else
    gtk3_value=1; gtk4_value=true; message="Switched to dark theme."
fi

sed -i "s/^$KEY=.*/$KEY=$gtk3_value/" "$GTK3_SETTINGS_FILE"
if [ -f "$GTK4_SETTINGS_FILE" ]; then
    sed -i "s/^$KEY=.*/$KEY=$gtk4_value/" "$GTK4_SETTINGS_FILE"
fi
echo "$message"

# The gtk-theme listener re-themes on this change; without it, do it here.
if ! pgrep -f "$SHROOMERY_DIR/listeners/gtk-theme.sh" >/dev/null; then
    "$SHROOMERY_SCRIPTS/apply-theme.sh" --reapply
fi
